  FlowLayoutPanel Row(){return new FlowLayoutPanel{Width=374,Height=48,Margin=new Padding(0,2,0,2),WrapContents=false};}
  Button Button(string text,Action action){var b=new SoftButton{Text=text,Width=179,Height=40,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(237,244,251),ForeColor=PanelTheme.Ink,Margin=new Padding(0,2,8,2),Cursor=Cursors.Hand};if(text=="Кирпичик · снежная форма"){b.Image=BrickArt.Icon;b.TextImageRelation=TextImageRelation.ImageBeforeText;}if(text=="Варежка"||text=="Лопата"){b.Image=text=="Варежка"?ToolArt.MittenIcon:ToolArt.ShovelIcon;b.ImageAlign=ContentAlignment.MiddleLeft;b.TextImageRelation=TextImageRelation.ImageBeforeText;}b.Font=new Font("Segoe UI Semibold",9.5f);if(text=="Выключить эффект"||text=="Остановить снегопад")b.Selected=true;b.Click+=delegate{action();};return b;}
  Label TextLabel(string text,int width){return new Label{Text=text,Width=width,AutoSize=false,Height=Measure(text),ForeColor=PanelTheme.Muted,Margin=new Padding(0,5,0,7)};}
  int Measure(string text){return Math.Max(40,TextRenderer.MeasureText(text,Font,new Size(360,0),TextFormatFlags.WordBreak).Height+10);}
  void Section(string text){body.Controls.Add(new Label{Text=text,Width=366,Height=32,ForeColor=PanelTheme.Purple,Font=new Font("Segoe UI Semibold",9),Margin=new Padding(0,16,0,0)});}
  void Check(string text,bool value,Action<bool> action){var c=new CheckBox{Text=text,Checked=value,Width=366,Height=40,Margin=new Padding(0,1,0,2)};c.CheckedChanged+=delegate{action(c.Checked);app.Save();};body.Controls.Add(c);}
  void Slider(string title,int min,int max,Func<int> read,Action<int> write,bool weather=true){var box=new SoftCard{Width=366,Height=80,Margin=new Padding(0,4,0,4)};var label=new Label{Text=title+"   "+read(),Dock=DockStyle.Top,Height=23,ForeColor=ink,BackColor=Color.FromArgb(239,246,252)};var t=new TrackBar{Minimum=min,Maximum=max,Value=read(),Dock=DockStyle.Bottom,Height=38,TickStyle=TickStyle.None,SmallChange=1,LargeChange=10,BackColor=Color.FromArgb(239,246,252)};t.Tag=new Action(delegate{t.Value=read();label.Text=title+"   "+read();});t.ValueChanged+=delegate{if(syncing)return;write(t.Value);label.Text=title+"   "+t.Value;if(weather)preset.SelectedIndex=3;};t.MouseUp+=delegate{app.Save();};box.Controls.Add(label);box.Controls.Add(t);body.Controls.Add(box);}
  void AudioSlider(string title,Func<int> read,Action<int> write){var card=new SoftCard{Width=366,Height=80,Margin=new Padding(0,4,0,4)};var label=new Label{Text=title+" · "+read()+"%",Dock=DockStyle.Top,Height=23,BackColor=Color.FromArgb(239,246,252)};var slider=new TrackBar{Minimum=0,Maximum=100,Value=read(),Dock=DockStyle.Bottom,Height=38,TickStyle=TickStyle.None,BackColor=Color.FromArgb(239,246,252)};slider.ValueChanged+=delegate{write(slider.Value);label.Text=title+" · "+slider.Value+"%";app.Audio.Update(app.World,app.Enabled&&!app.SystemPause);};slider.MouseUp+=delegate{app.Save();};slider.KeyUp+=delegate{app.Save();};card.Controls.Add(label);card.Controls.Add(slider);body.Controls.Add(card);}
  void RebindSliders(){syncing=true;foreach(Control p in body.Controls)foreach(Control c in p.Controls)if(c is TrackBar&&c.Tag is Action)((Action)c.Tag)();syncing=false;}
  public void RefreshState(){if(IsDisposed)return;string state=!app.Enabled?"Эффект выключен":app.SystemPause?"Пауза: полноэкранное приложение или блокировка":app.World.Paused?"Симуляция на паузе":(app.World.Emitting?"Снег идёт · ":"Снегопад остановлен · ")+app.World.Flakes.Count+" снежинок";status.Text=state+(app.Notice.Length>0?"\n"+app.Notice:"");status.Height=Measure(status.Text);enable.Text=app.Enabled?"Выключить эффект":"Включить эффект";pause.Text=app.World.Paused?"Продолжить":"Пауза";emit.Text=app.World.Emitting?"Остановить снегопад":"Продолжить снегопад";MarkTools(body);toolStatus.Text="Сейчас: "+(app.World.Tool==Tool.None?"обычная работа · кирпичики можно брать":app.World.Tool==Tool.Brick?"кирпичик":app.World.Tool==Tool.Handful?"горсть":app.World.Tool==Tool.Snowball?"снежок":app.World.Tool==Tool.Mitten?"варежка":"лопата");}
  void MarkTools(Control root){foreach(Control c in root.Controls){var button=c as SoftButton;if(button!=null){string name=app.World.Tool==Tool.Brick?"Кирпичик · снежная форма":app.World.Tool==Tool.Handful?"Горсть · зачерпнуть и бросить":app.World.Tool==Tool.Snowball?"Снежок":app.World.Tool==Tool.Mitten?"Варежка":app.World.Tool==Tool.Shovel?"Лопата":"Без инструмента";if(button.Text=="Кирпичик · снежная форма"||button.Text=="Горсть · зачерпнуть и бросить"||button.Text=="Снежок"||button.Text=="Варежка"||button.Text=="Лопата"||button.Text=="Без инструмента"){bool selected=button.Text==name;if(button.Selected!=selected){button.Selected=selected;button.Invalidate();}}}if(c.HasChildren)MarkTools(c);}}
  internal void ExportPreview(string dir){System.IO.Directory.CreateDirectory(dir);PerformLayout();using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(System.IO.Path.Combine(dir,"interface-v09.png"));}body.AutoScrollPosition=new Point(0,570);PerformLayout();using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(System.IO.Path.Combine(dir,"interface-tools-v09.png"));}body.AutoScrollPosition=new Point(0,1250);PerformLayout();using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(System.IO.Path.Combine(dir,"interface-audio-v09.png"));}body.AutoScrollPosition=Point.Empty;}
  protected override void OnFormClosing(FormClosingEventArgs e){if(!app.Exiting){e.Cancel=true;Hide();app.Save();}base.OnFormClosing(e);}
  protected override void OnHandleCreated(EventArgs e){base.OnHandleCreated(e);registeredHandle=Handle;if(app!=null)app.Tracker.NoSupport.Add(registeredHandle);}
  protected override void OnHandleDestroyed(EventArgs e){if(app!=null)app.Tracker.NoSupport.Remove(registeredHandle);registeredHandle=IntPtr.Zero;base.OnHandleDestroyed(e);}
