    using(var b=new SolidBrush(PanelTheme.Cyan))g.FillEllipse(b,Width-82,99,36,36);using(var pen=new Pen(Color.White,1.5f))for(int i=0;i<6;i++){double a=i*Math.PI/3;g.DrawLine(pen,Width-64,117,Width-64+(float)Math.Cos(a)*10,117+(float)Math.Sin(a)*10);}
    using(var f=new Font("Segoe UI Semibold",29))g.DrawString("Снег",f,Brushes.White,35,32);using(var f=new Font("Segoe UI",10.5f))using(var b=new SolidBrush(Color.FromArgb(226,224,255)))g.DrawString("Маленькая зима\nна вашем рабочем столе",f,b,38,91);
   }
